const PAGE_TABS_WIDE = window.matchMedia ? window.matchMedia("(min-width: 1200px)") : null;

const TOP_TITLE_WIDE = window.matchMedia ? window.matchMedia("(min-width: 1700px)") : null;

function assetPins() {
  try { const v = JSON.parse(localStorage.getItem("snapPins") || "null"); if (Array.isArray(v)) return new Set(v); } catch (e) { /* 기억은 편의 */ }
  return new Set(["eth", "sol", "xrp", "sndk"]);
}


function renderSnapshotAssetTabs() {
  const cn = el("fpCoinSym"); if (cn) cn.textContent = String(activeSnapshotAsset || "eth").toUpperCase();
  const cb = el("fpCoinBtnSym"); if (cb) cb.textContent = String(activeSnapshotAsset || "eth").toUpperCase();   // 전체화면 코인 이름(시안 B)
  document.querySelectorAll("#snapshotAssetTabs .asset-tab").forEach((btn) => {
    const on = !enabledAssets || enabledAssets.includes(btn.dataset.asset);
    // 🔴목록을 받기 전(enabledAssets === null)에는 **되살리지 않는다**.
    //   서버가 index 를 내보낼 때 꺼진 코인에 hidden 을 붙여 주는데(dashboard_index::
    //   _hide_off_assets), 여기서 무조건 `btn.hidden = !on` 을 쓰면 app.js 가 뜨자마자
    //   그걸 전부 되돌려 «5개 번쩍 → ETH 만» 이 된다(실측: 350ms 에 5개, 800ms 에 ETH).
    //   fail-open 은 그대로다 -- 구버전 서버는 hidden 을 안 붙이므로 계속 전부 보인다.
    if (enabledAssets) btn.hidden = !on;
    btn.classList.toggle("active", on && btn.dataset.asset === activeSnapshotAsset);
  });
  // 2026-11-02 칩 = 고정한 것 + 지금 보는 것만(나머지는 «전체 ▾» 팝오버) -- off-chip 은 CSS 가 가린다.
  const pins = assetPins();
  document.querySelectorAll("#snapshotAssetTabs .asset-tab").forEach((btn) => btn.classList.toggle("off-chip", !pins.has(btn.dataset.asset) && btn.dataset.asset !== activeSnapshotAsset));
  const allOn = [...document.querySelectorAll("#snapshotAssetTabs .asset-tab")].filter((b) => !b.hidden), mn = el("assetMoreN"), mc = el("assetCur");
  if (mn) mn.textContent = String(allOn.length);
  if (mc) mc.textContent = String(activeSnapshotAsset || "eth").toUpperCase();   // 2026-11-04 모바일: 칩 대신 이 버튼 하나가 지금 코인을 말한다
  // 2026-10-01 코인 탭 = 1h~12h 와 같은 세그먼트(사용자 지시) -- 숨은 코인(BTC·HYPE)은 칸이 아니므로 «보이는 칸» 기준으로 조각 폭·위치를 준다.
  const host = el("snapshotAssetTabs"), vis = allOn.filter((b) => !b.classList.contains("off-chip"));
  if (host) { host.style.setProperty("--seg-n", String(vis.length || 1)); host.style.setProperty("--i", String(Math.max(0, vis.findIndex((b) => b.classList.contains("active"))))); }
}


function placeTopLeft() {
  const top = document.querySelector(".topbar"), slot = el("topLeftSlot"), mid = el("topCenterSlot");
  const coins = el("assetBar"), home = el("coinHome"), sess = document.querySelector(".top-right"), theme = el("themeToggle");
  const title = el("fpCoinName"), tools = document.querySelector("#fpCard .ops-health-head-tools");
  if (!top || !slot || !mid) return;
  if (PAGE_TABS_WIDE && PAGE_TABS_WIDE.matches) {
    if (sess && sess.parentElement !== slot) slot.appendChild(sess);
    if (TOP_TITLE_WIDE && TOP_TITLE_WIDE.matches) {
      if (coins && theme && coins.nextElementSibling !== theme) theme.before(coins);
    } else if (coins && coins.parentElement !== mid) mid.appendChild(coins);
  } else {
    if (coins && home && coins.previousElementSibling !== home) home.after(coins);
    if (sess && sess.parentElement !== top) top.appendChild(sess);
  }
  const atTop = !!(PAGE_TABS_WIDE && PAGE_TABS_WIDE.matches && TOP_TITLE_WIDE && TOP_TITLE_WIDE.matches);
  if (title) {
    if (atTop) { if (title.parentElement !== mid) mid.appendChild(title); }
    else if (title.parentElement === mid) tools.before(title);   // 제자리(카드 머리)
  }
}
